head.script:
// https://inswave01.atlassian.net/browse/WAEA-1208
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.gVar = {};



// 다운로드 데이터가 여러 번에 나누어 생성될 만큼 큰 규모(3000 행)를 바인딩한다.
scwin.onpageload = function () {
    var arrDept = ["영업1팀", "영업2팀", "개발1팀", "개발2팀", "품질보증팀", "인사팀", "재무팀"];
    var arrData = [];

    for (var i = 0; i < 3000; i++) {
        arrData.push({
            "empNo" : "E" + ("00000" + (i + 1)).slice(-5),
            "empName" : "사원" + (i + 1),
            "deptName" : arrDept[i % arrDept.length],
            "salary" : (3200000 + (i % 47) * 50000) + ""
        });
    }

    dlt_down.setJSON(arrData);
};



// 다운로드 진행 중 발생하는 스크립트 오류 횟수를 센다.
scwin.startErrorCount = function () {
    scwin.gVar.errorCount = 0;

    if (scwin.gVar.orgConsoleError) return;

    scwin.gVar.orgConsoleError = console.error;
    console.error = function () {
        scwin.gVar.errorCount++;
        return scwin.gVar.orgConsoleError.apply(console, arguments);
    };
};

// 오류 감시를 원복한다.
scwin.stopErrorCount = function () {
    if (scwin.gVar.orgConsoleError) {
        console.error = scwin.gVar.orgConsoleError;
        scwin.gVar.orgConsoleError = null;
    }
};



// 확인 레이어에 표시된 진행률 문구를 읽는다.
scwin.getConfirmLayerText = function () {
    try {
        var objFrame = document.getElementById("gridDownLoadLayer");
        if (objFrame === null || !objFrame.contentDocument) return null;
        var objText = objFrame.contentDocument.getElementById("textLayer");
        return (objText === null) ? null : objText.textContent;
    } catch (e) {
        return null;
    }
};

// 확인 레이어의 download 버튼이 눌릴 수 있는 상태인지(데이터 생성 완료 여부) 확인한다.
scwin.isConfirmLayerReady = function () {
    try {
        var objFrame = document.getElementById("gridDownLoadLayer");
        if (objFrame === null || !objFrame.contentDocument) return false;
        var objBtn = objFrame.contentDocument.getElementById("downloadButton");
        return (objBtn !== null && objBtn.disabled === false);
    } catch (e) {
        return false;
    }
};



// 확인 레이어의 진행률 문구 변화를 감시하여 진행률 표시가 갱신된 횟수를 센다.
scwin.startProgressWatch = function () {
    scwin.gVar.progressCount = 0;
    scwin.gVar.progressSeen = {};
    scwin.gVar.lastText = null;

    scwin.gVar.watchTimer = setInterval(function () {
        var strText = scwin.getConfirmLayerText();
        if (strText === null || strText === scwin.gVar.lastText) return;
        scwin.gVar.lastText = strText;

        if (strText.indexOf("%") !== -1 && scwin.gVar.progressSeen[strText] !== true) {
            scwin.gVar.progressSeen[strText] = true;
            scwin.gVar.progressCount++;
        }
    }, 5);
};

scwin.stopProgressWatch = function () {
    if (scwin.gVar.watchTimer) {
        clearInterval(scwin.gVar.watchTimer);
        scwin.gVar.watchTimer = null;
    }
};



// [결함] showConfirm = true 로 다운로드
scwin.btn_showConfirm_onclick = function () {
    scwin.startErrorCount();
    scwin.startProgressWatch();

    target1.advancedExcelDownload({
        "fileName" : "fail_showconfirm",
        "extension" : "xlsx",
        "showConfirm" : true
    });

    scwin.waitConfirmDone(0);
};

// 데이터 생성이 끝날 때까지 기다렸다가 결과를 출력한다.
scwin.waitConfirmDone = function (nRetry) {
    if (scwin.isConfirmLayerReady() !== true && nRetry < 160) {
        setTimeout(function () { scwin.waitConfirmDone(nRetry + 1); }, 50);
        return;
    }

    scwin.stopProgressWatch();
    scwin.stopErrorCount();

    scwin.setReturnValue("호출 : showConfirm = true");
    scwin.setReturnValue("진행률 표시 갱신 횟수 : " + scwin.gVar.progressCount);
    scwin.setReturnValue("오류 발생 횟수 : " + scwin.gVar.errorCount);
    scwin.setReturnValue("");
};



// [비교] showConfirm 생략 (확인 레이어 없음)
scwin.btn_noConfirm_onclick = function () {
    scwin.startErrorCount();

    target1.advancedExcelDownload({
        "fileName" : "ok_noconfirm",
        "extension" : "xlsx"
    });

    setTimeout(function () {
        scwin.stopErrorCount();
        scwin.setReturnValue("호출 : showConfirm 생략");
        scwin.setReturnValue("오류 발생 횟수 : " + scwin.gVar.errorCount);
        scwin.setReturnValue("");
    }, 5000);
};
